import{_ as e,c as t,o as r,i as o}from"./entry.969638ee.js";const a={},s=o('<h3>Front-end Developer</h3><h4>SmartSurvey, remote (Aug 2023 – June 2025)</h4><hr><p> At <a href="https://www.smartsurvey.co.uk/" target="_blank" rel="noopener noreferrer" class="text-white">SmartSurvey</a>, a survey and feedback SaaS, I built front ends for two new products: survey results dashboards and AI open-text analysis (topic categorisation and sentiment). </p><p> Replaced a 3,000-line mixin behind the report-builder controls with a type-safe config, which I prototyped and pitched and the team adopted. It became the single source of truth, replacing the product team’s spreadsheet of rules, and new features in the area stopped causing regressions. </p><p>Migrated legacy Vue 2 code to Vue 3 with full TypeScript support.</p><p> In a team with no tech lead, introduced technical design calls before each piece of work, which cut duplicated effort. </p><p>Mentored junior developers through pairing, code review and talks.</p><p><strong>Technologies: </strong>Vue, TypeScript, Bootstrap/SCSS, Jest, Vue Test Utils, C#/.NET, PostgreSQL, Azure DevOps </p>',9),n=[s];function c(i,p){return r(),t("div",null,n)}const u=e(a,[["render",c]]);export{u as default};
